class _Safe(dict):
    def __missing__(self, key):
        return "{" + key + "}"


def t(key: str, **params) -> str:
    lang = st.session_state.get("lang", "zh")
    pair = S.get(key)
    if pair is None:
        return key
    text = pair[0] if lang == "zh" else pair[1]
    return text.format_map(_Safe(params)) if params else text
